#include <iostream>
#include <string>
using namespace std;

class SinhVien {
private:
    string hoTen;
    double gpa;

public:
    // Constructor (Ham khoi tao)
    SinhVien(string ten, double diem) {
        hoTen = ten;
        setGpa(diem); // Su dung setter de kiem soat tinh hop le
    }

    // Setter co kiem tra hop le
    void setGpa(double diem) {
        if (diem >= 0.0 && diem <= 4.0) {
            gpa = diem;
        } else {
            gpa = 0.0;
            cout << "Canh bao: Diem GPA khong hop le!" << endl;
        }
    }

    // Getter
    double getGpa() const { return gpa; }
    string getHoTen() const { return hoTen; }

    void xuatThongTin() const {
        cout << "Sinh vien: " << hoTen << " | GPA: " << gpa << endl;
    }
};

int main() {
    SinhVien sv("Nguyen Van An", 3.75);
    sv.xuatThongTin();

    // sv.gpa = 10; // LOI BIEN DICH: gpa la private, khong the sua truc tiep!
    return 0;
}
